            // Respond to the launch request. 
            guard let token = userActivity.userInfo?[BEBrowserDataExportManager
                .exportTokenUserInfoKey] as? UUID else { return }            
            Task {
                // Export browser data.
                await handleExportRequest(with: token)
            }
        }
    }
}
